import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { trpc } from "@/utils/trpc";
import { useQuery } from "@tanstack/react-query";
import { Link } from "@tanstack/react-router";
import { BookOpen, Clock, PlayCircle, Trophy } from "lucide-react";
import dayjs from "dayjs";
import { Pagination } from "./pagination";
import ImageWithFallback from "@/components/image-with-fallback";

interface ElearningTabProps {
  page: number;
  limit: number;
  onPageChange: (page: number) => void;
}

export function ElearningTab({ page, limit, onPageChange }: ElearningTabProps) {
  const { data, isLoading } = useQuery(
    trpc.pelatihan.enrollment.getUserEnrollmentsByType.queryOptions({
      type: "elearning",
      page,
      limit,
    }),
  );

  if (isLoading) {
    return (
      <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {[1, 2, 3].map((i) => (
          <Card key={i} className="animate-pulse border-slate-100 shadow-sm">
            <div className="h-40 bg-slate-100" />
            <CardHeader className="space-y-2">
              <div className="h-4 w-3/4 rounded bg-slate-100" />
              <div className="h-4 w-1/2 rounded bg-slate-100" />
            </CardHeader>
            <CardContent>
              <div className="h-2 w-full rounded bg-slate-100" />
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  const enrollments = data?.data ?? [];
  const totalPages = data?.pagination?.totalPages ?? 0;

  if (enrollments.length === 0) {
    return (
      <div className="flex h-64 flex-col items-center justify-center rounded-2xl border border-dashed border-slate-200 bg-white p-6 text-center">
        <div className="mb-4 rounded-full bg-blue-50 p-4">
          <BookOpen className="h-6 w-6 text-[#1061D6]" />
        </div>
        <p className="font-['Plus_Jakarta_Sans'] text-sm font-bold text-slate-800">
          Belum ada kelas E-Learning
        </p>
        <p className="mb-6 max-w-sm font-['Poppins'] text-xs text-slate-500">
          Anda belum terdaftar di kelas E-Learning manapun. Silakan lihat
          katalog pelatihan kami.
        </p>
        <Button
          className="rounded-xl bg-[#1061D6] font-bold text-white hover:bg-[#1061D6]/90"
          asChild
        >
          <Link to="/pelatihan">Jelajahi Katalog</Link>
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {enrollments.map((enrollment) => (
          <Card
            key={enrollment.id}
            className="flex flex-col overflow-hidden border-slate-100 shadow-sm transition-all hover:border-[#1061D6]/10 hover:shadow-md"
          >
            <div className="relative h-40 shrink-0 bg-slate-50">
              <ImageWithFallback
                src={enrollment.pelatihan.thumbnailUrl ?? ""}
                alt={enrollment.pelatihan.title}
                imgClassName="h-full w-full object-cover"
              />
            </div>
            <CardHeader className="pt-4 pb-3">
              <div className="mb-1 flex flex-wrap gap-1">
                <span
                  className={`inline-flex items-center rounded-md px-2 py-0.5 text-[10px] font-bold tracking-wider uppercase ${
                    enrollment.status === "completed"
                      ? "bg-emerald-50 text-emerald-700"
                      : enrollment.status === "in_progress"
                        ? "bg-blue-50 text-[#1061D6]"
                        : "bg-slate-100 text-slate-700"
                  }`}
                >
                  {enrollment.status === "completed"
                    ? "Selesai"
                    : enrollment.status === "in_progress"
                      ? "Sedang Berjalan"
                      : "Terdaftar"}
                </span>

                {enrollment.verificationStatus === "pending" && (
                  <span className="inline-flex items-center rounded-md bg-amber-50 px-2 py-0.5 text-[10px] font-bold tracking-wider text-amber-700 uppercase">
                    Menunggu Verifikasi
                  </span>
                )}
                {enrollment.verificationStatus === "rejected" && (
                  <span className="inline-flex items-center rounded-md bg-rose-50 px-2 py-0.5 text-[10px] font-bold tracking-wider text-rose-700 uppercase">
                    Ditolak
                  </span>
                )}
              </div>
              <CardTitle className="line-clamp-2 font-['Plus_Jakarta_Sans'] text-sm leading-tight font-bold text-slate-800">
                {enrollment.pelatihan.title}
              </CardTitle>
              <CardDescription className="flex items-center gap-1 font-['Poppins'] text-[10px] font-semibold text-slate-400">
                <Clock className="h-3 w-3" /> Terdaftar pada{" "}
                {dayjs(enrollment.enrolledAt).format("DD MMM YYYY")}
              </CardDescription>
            </CardHeader>
            <CardContent className="flex-1 pb-3">
              <div className="space-y-1">
                <div className="flex justify-between font-['Poppins'] text-xs font-semibold text-slate-500">
                  <span>Progres</span>
                  <span>{enrollment.progressPercentage}%</span>
                </div>
                <Progress
                  value={enrollment.progressPercentage}
                  className="h-1.5 bg-slate-100"
                />
                {enrollment.verificationStatus === "rejected" &&
                  enrollment.rejectionReason && (
                    <p className="mt-2 font-['Poppins'] text-[10px] font-medium text-rose-600">
                      Alasan penolakan: {enrollment.rejectionReason}
                    </p>
                  )}
              </div>
            </CardContent>
            <CardFooter className="border-t border-slate-50 pt-3 pb-4">
              {enrollment.verificationStatus !== "verified" ? (
                <Button
                  className="w-full rounded-xl font-bold"
                  variant="secondary"
                  disabled
                >
                  {enrollment.verificationStatus === "pending"
                    ? "Menunggu Verifikasi Admin"
                    : "Pendaftaran Ditolak"}
                </Button>
              ) : enrollment.status === "completed" ? (
                <Button
                  className="w-full rounded-xl border-slate-200 font-bold text-[#1061D6]"
                  variant="outline"
                  asChild
                >
                  <Link
                    to="/dashboard/pelatihan/$enrollmentId/materi"
                    params={{ enrollmentId: enrollment.id }}
                  >
                    <Trophy className="mr-1.5 h-4 w-4" />
                    Lihat Materi
                  </Link>
                </Button>
              ) : (
                <Button
                  className="w-full rounded-xl bg-[#1061D6] font-bold text-white hover:bg-[#1061D6]/90"
                  asChild
                >
                  <Link
                    to="/dashboard/pelatihan/$enrollmentId/materi"
                    params={{ enrollmentId: enrollment.id }}
                  >
                    <PlayCircle className="mr-1.5 h-4 w-4" />
                    {enrollment.progressPercentage > 0
                      ? "Lanjutkan Belajar"
                      : "Mulai Belajar"}
                  </Link>
                </Button>
              )}
            </CardFooter>
          </Card>
        ))}
      </div>

      <Pagination
        currentPage={page}
        totalPages={totalPages}
        onPageChange={onPageChange}
      />
    </div>
  );
}

